@Override
public void visitAttribute(XmlContext context, Attr attribute) {
    String value = attribute.getValue();
    if (value == null || value.isEmpty()) {
        return;
    }
    if (ON_CLICK.equals(attribute.getLocalName())) {
        if (!ANDROID_URI.equals(attribute.getNamespaceURI())) return;
        if (value.startsWith("@") || value.startsWith("{")) return;
        String file = context.file.getPath();
        mReferences.computeIfAbsent(file, k -> new ArrayList<>()).add(new Pair<>(value, context.getValueLocation(attribute)));
    } else if (attribute.getLocalName().equals("context") && TOOLS_URI.equals(attribute.getNamespaceURI())) {
        String file = context.file.getPath();
        String[] classes = value.split(",");
        for (String cls : classes) {
            cls = cls.trim();
            if (!cls.isEmpty()) {
                mContexts.computeIfAbsent(file, k -> new ArrayList<>()).add(cls);
            }
        }
    }
}
```

